definition.script:
pipeline {
    agent any

    environment {
        PYTHON_PATH = 'C:\\Users\\DAVID\\AppData\\Local\\Programs\\Python\\Python311\\python.exe'
        EMAIL_USER = credentials('gmail-user')
        EMAIL_PASS = credentials('gmail-app-password')
        EMAIL_TO   = 'destinatario@gmail.com'
    }

    stages {

        stage('Preparar') {
            steps {
                bat '"%PYTHON_PATH%" -m pip install pandas'
                bat '"%PYTHON_PATH%" -m pip install openpyxl'
                bat '"%PYTHON_PATH%" -m pip install reportlab'
            }
        }

        stage('READ') {
            steps {
                bat '"%PYTHON_PATH%" "%WORKSPACE%\\data_read.py"'
            }
        }

        stage('TRANSFORM') {
            steps {
                bat '"%PYTHON_PATH%" "%WORKSPACE%\\data_transform.py"'
            }
        }

        stage('EXPORT') {
            steps {
                bat '"%PYTHON_PATH%" "%WORKSPACE%\\data_export.py"'
            }
        }

        stage('SEND_MAIL') {
            steps {
                bat '"%PYTHON_PATH%" "%WORKSPACE%\\send_mail.py"'
            }
        }
    }

    post {
        success {
            echo 'Pipeline ejecutado correctamente. Reporte generado y correo enviado.'
        }
        failure {
            echo 'El pipeline falló. Revisar consola de Jenkins.'
        }
    }
}
